-- RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public
-- AS $$ SELECT EXISTS (SELECT 1 FROM public.conversation_participants
--                       WHERE conversation_id = conv AND user_id = uid); $$;
